      "year": 3500,
      "event": "First contact with extraterrestrial microbial life.",
      "detail": "Probes discover complex organisms in Europa's ocean. Analysis reveals non-DNA biochemistry, reshaping understanding of biology."
    },
    {
      "year": 4000,
      "event": "Dyson sphere construction begins around Sol.",
